/**
 * @file src/ui/tooltips.ts
 * Helpers pour tooltips et prestige
 */

import { ALL_ITEMS } from '../../constants/balance/shopAndAggregation.ts';
import { formatPrestigeSuffixSpaced, getShardKey } from '../../formatters.ts';
import { cardResolvePrestigeCosts } from '../lib/cardPrestigeUi.ts';
import { uiPokemonName, uiText } from './i18n.ts';
import type { CreatureData, GameRuntime, TeamTooltipOptions, TooltipStatSlice } from './uiTypes.ts';

export function _tooltipInt(value: unknown): number {
    const n = Number(value);
    if (!Number.isFinite(n)) return 0;
    return Math.floor(n);
}

export function _uiGetPrestigeCost(game: GameRuntime | null | undefined, prestige: number): number {
    if (game && typeof game.getPrestigeCost === 'function') {
        return game.getPrestigeCost(prestige);
    }
    return Math.max(1, (Number(prestige) || 0) + 1);
}

export function _uiGetPrestigeStoneCost(game: GameRuntime | null | undefined, prestige: number): number {
    if (game && typeof game.getPrestigeStoneCost === 'function') {
        return game.getPrestigeStoneCost(prestige);
    }
    return _uiGetPrestigeCost(game, prestige);
}

export function _uiPrestigeStoneIconUrl(): string {
    const def = ALL_ITEMS.prestige_stone as { img?: string } | undefined;
    return (def?.img) ? def.img : 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/items/comet-shard.png';
}

function scalarToDisplayString(value: unknown): string {
    if (value == null) return '';
    if (typeof value === 'string' || typeof value === 'number' || typeof value === 'boolean') return String(value);
    return '';
}

export function _tooltipEscapeHtml(value: unknown): string {
    return scalarToDisplayString(value)
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&#39;');
}

export function _tooltipBuildStatGrid(
    stats: TooltipStatSlice,
    options: { signed?: boolean } = {},
): string {
    const signed = !!options.signed;
    const defs: Array<{ key: keyof TooltipStatSlice; label: string; cls: string }> = [
        { key: 'maxHp', label: 'HP', cls: 'hp' },
        { key: 'attack', label: 'ATK', cls: 'atk' },
        { key: 'spattack', label: 'ATK SP', cls: 'spatk' },
        { key: 'defense', label: 'DEF', cls: 'def' },
        { key: 'spdefense', label: 'DEF SP', cls: 'spdef' },
        { key: 'speed', label: 'SPD', cls: 'spd' },
    ];

    return `
        <div class="team-tooltip-stat-grid">
            ${defs.map((def) => {
                const raw = _tooltipInt(stats[def.key]);
                const valueText = signed ? (raw >= 0 ? `+${raw}` : `${raw}`) : `${raw}`;
                return `
                    <div class="team-tooltip-stat-cell">
                        <span class="team-tooltip-stat-pill ${def.cls}">${def.label}</span>
                        <span class="team-tooltip-stat-value">${valueText}</span>
                    </div>
                `;
            }).join('')}
        </div>
    `;
}

export function getTeamAreaCreatureTooltipTitle(
    creature: CreatureData | null | undefined,
    gameRef?: GameRuntime | null,
): string {
    if (!creature) return 'Pokemon';
    const shadowPrefix = creature.isShadow ? 'Shadow ' : '';
    const shinyPrefix = creature.isShiny ? 'Shiny ' : '';
    const prefix = shadowPrefix || shinyPrefix;
    const prestige = Number(creature.prestige) || 0;
    const displayName = uiPokemonName(gameRef, creature.name);
    return `${prefix}${displayName}${formatPrestigeSuffixSpaced(prestige)}`;
}

export function buildTeamAreaCreatureTooltip(
    game: GameRuntime,
    creature: CreatureData,
    options: TeamTooltipOptions = {},
): string {
    if (!game || !creature) return '';
    const prestige = Number(creature.prestige) || 0;
    const expToNext = Math.max(1, Number(creature.expToNext) || 1);
    const expValue = Math.max(0, Number(creature.exp) || 0);
    const expPercent = Math.max(0, Math.min(100, (expValue / expToNext) * 100));
    const shardKey = getShardKey(creature.name, creature.rarity);
    const currentShards = Number(game.shards[shardKey]) || 0;
    const catchUpCosts = cardResolvePrestigeCosts(game, creature);
    const prestigeCost = catchUpCosts.shards;
    const prestigeStoneCost = catchUpCosts.stones;
    const currentPrestigeStones = (game.items?.prestige_stone) ? Number(game.items.prestige_stone) || 0 : 0;
    const teamContributionRate = Number(options.teamContributionRate) || 0;
    const pensionContributionRate = Number(options.pensionContributionRate) || 0;
    const metaChips = [
        `<span class="team-tooltip-meta-chip">${uiText('state.levelShort', 'Lvl')} ${_tooltipInt(creature.level)}</span>`,
        `<span class="team-tooltip-meta-chip">EXP ${_tooltipInt(expValue)}/${_tooltipInt(expToNext)} (${expPercent.toFixed(1)}%)</span>`,
        `<span class="team-tooltip-meta-chip">Shards ${_tooltipInt(currentShards)}/${_tooltipInt(prestigeCost)}</span>`,
        `<span class="team-tooltip-meta-chip">${uiText('tooltip.prestigeStones', 'Prestige stones')} ${_tooltipInt(currentPrestigeStones)}/${_tooltipInt(prestigeStoneCost)}</span>`,
    ];
    if (options.locationLabel) {
        metaChips.push(`<span class="team-tooltip-meta-chip">${_tooltipEscapeHtml(options.locationLabel)}</span>`);
    }

    const extraLines = Array.isArray(options.extraLines)
        ? options.extraLines
            .filter((line): line is string => line != null && String(line).trim().length > 0)
            .map((line) => `<div class="team-tooltip-extra-line">${_tooltipEscapeHtml(line)}</div>`)
            .join('')
        : '';

    let html = `
        <div class="team-tooltip-body">
            <div class="team-tooltip-meta-row">${metaChips.join('')}</div>
            ${extraLines ? `<div class="team-tooltip-extra">${extraLines}</div>` : ''}
            <div class="team-tooltip-section-label">${uiText('tooltip.teamStats', 'Stats')}</div>
            ${_tooltipBuildStatGrid(creature)}
    `;

    if (teamContributionRate > 0) {
        html += `
            <div class="team-tooltip-section-label">${uiText('tooltip.teamContribution', 'Team contribution ({percent}%)', { percent: (teamContributionRate * 100).toFixed(0) })}</div>
            ${_tooltipBuildStatGrid({
                maxHp: creature.maxHp * teamContributionRate,
                attack: creature.attack * teamContributionRate,
                spattack: creature.spattack * teamContributionRate,
                defense: creature.defense * teamContributionRate,
                spdefense: creature.spdefense * teamContributionRate,
                speed: creature.speed * teamContributionRate,
            }, { signed: true })}
        `;
    }

    if (pensionContributionRate > 0) {
        html += `
            <div class="team-tooltip-section-label">${uiText('tooltip.daycareContribution', 'Daycare contribution ({percent}%)', { percent: (pensionContributionRate * 100).toFixed(0) })}</div>
            ${_tooltipBuildStatGrid({
                maxHp: creature.maxHp * pensionContributionRate,
                attack: creature.attack * pensionContributionRate,
                spattack: creature.spattack * pensionContributionRate,
                defense: creature.defense * pensionContributionRate,
                spdefense: creature.spdefense * pensionContributionRate,
                speed: creature.speed * pensionContributionRate,
            }, { signed: true })}
        `;
    }

    html += '</div>';
    return html;
}
